/* Version script for libchidori.so
 * Makes our cuBLAS/cuBLASLt symbols match PyTorch's versioned references.
 * Without this, PyTorch's ELF imports like cublasGemmEx@libcublas.so.12
 * skip our unversioned exports and go to the real library. */

libcublas.so.12 {
    global:
        cublasCreate_v2;
        cublasDestroy_v2;
        cublasSetStream_v2;
        cublasGetStream_v2;
        cublasSetMathMode;
        cublasGetMathMode;
        cublasGetVersion_v2;
        cublasSgemm_v2;
        cublasDgemm_v2;
        cublasHgemm;
        cublasSgemmEx;
        cublasGemmEx;
        cublasSgemv_v2;
        cublasDgemv_v2;
        cublasSaxpy_v2;
        cublasDaxpy_v2;
        cublasSnrm2_v2;
        cublasDnrm2_v2;
        cublasSdot_v2;
        cublasDdot_v2;
        cublasSscal_v2;
        cublasDscal_v2;
        cublasScopy_v2;
        cublasDcopy_v2;
        cublasSgemmBatched;
        cublasSgemmStridedBatched;
        cublasGemmStridedBatchedEx;
        cublasGemmBatchedEx;
        cublasGetProperty;
        cublasSetWorkspace_v2;
        cublasSetPointerMode_v2;
        cublasGetPointerMode_v2;
        cublasSetAtomicsMode;
        cublasGetAtomicsMode;
        cublasLoggerConfigure;
};

libcublasLt.so.12 {
    global:
        cublasLtCreate;
        cublasLtDestroy;
        cublasLtMatmul;
        cublasLtMatmulDescCreate;
        cublasLtMatmulDescDestroy;
        cublasLtMatmulDescSetAttribute;
        cublasLtMatmulDescGetAttribute;
        cublasLtMatrixLayoutCreate;
        cublasLtMatrixLayoutDestroy;
        cublasLtMatrixLayoutSetAttribute;
        cublasLtMatrixLayoutGetAttribute;
        cublasLtMatmulPreferenceCreate;
        cublasLtMatmulPreferenceDestroy;
        cublasLtMatmulPreferenceSetAttribute;
        cublasLtMatmulAlgoGetHeuristic;
        cublasLtMatmulAlgoInit;
        cublasLtMatmulAlgoConfigSetAttribute;
        cublasLtMatmulAlgoConfigGetAttribute;
        cublasLtMatmulAlgoCheck;
        cublasLtMatmulAlgoGetIds;
        cublasLtGetStatusName;
        cublasLtGetStatusString;
        cublasLtGetProperty;
        cublasLtLoggerSetCallback;
        cublasLtLoggerSetLevel;
        cublasLtLoggerSetMask;
        cublasLtLoggerSetFile;
        cublasLtGetVersion;
};
